// spec: .qa/e2e/specs/search-prefs.md
// seed: tests/seed.free.geo.spec.ts
// Меняет предпочтения free → @data; исходные значения возвращаются в finally (REST, токеном free).
import { test, expect, type Page, type Request, type Response } from '@playwright/test';
import path from 'path';
import { ageValues, dragHandleTo } from './prefs-helpers';
import { restGet, type Api, type Row } from '../_shared/api';

// Мышью в Chromium с шириной телефона (проект data — Chromium).
test.use({
  storageState: path.resolve(__dirname, '../../../auth/free-r13.json'),
  viewport: { width: 390, height: 844 },
  colorScheme: 'dark',
});

const PREFS = '/prefs?from=settings';
const KEYS = ['pref_age_min', 'pref_age_max', 'pref_distance_km', 'interested_in'] as const;

async function apiFrom(page: Page, req: Request): Promise<Api> {
  const h = await req.allHeaders();
  const payload = JSON.parse(Buffer.from(h['authorization'].split(' ')[1].split('.')[1], 'base64url').toString('utf8'));
  return { page, base: req.url().split('/rest/v1/')[0], apikey: h['apikey'], auth: h['authorization'], userId: String(payload.sub) };
}

const readPrefs = async (api: Api): Promise<Row> =>
  (await (await restGet(api, `profiles?id=eq.${api.userId}&select=${KEYS.join(',')}`)).json())[0];

const isProfilePatch = (r: Request) => r.method() === 'PATCH' && r.url().includes('/rest/v1/profiles');
const patchBody = (r: Request): Row => {
  try { return (r.postDataJSON() ?? {}) as Row; } catch { return {}; }
};

// Геометрия ползунка расстояния: центры делений «1» и «100» и ось дорожки (тонкая полоса высотой ~4 px).
async function distanceGeo(page: Page) {
  return page.evaluate(() => {
    const leaves = [...document.querySelectorAll('div')].filter((d) => d.childElementCount === 0);
    const title = leaves.find((d) => d.textContent?.trim() === 'מרחק')!;
    const top = title.getBoundingClientRect().bottom;
    const below = leaves.filter((d) => d.getBoundingClientRect().top > top);
    const cx = (t: string) => { const r = below.find((d) => d.textContent?.trim() === t)!.getBoundingClientRect(); return r.x + r.width / 2; };
    const track = below.find((d) => { const r = d.getBoundingClientRect(); return r.height >= 3 && r.height <= 5 && r.width > 200; })!.getBoundingClientRect();
    return { x1: cx('1'), x100: cx('100'), y: track.y + track.height / 2 };
  });
}

const distanceLabel = (page: Page) => page.getByText(/^\d+ ק״מ$/);
const distanceValue = async (page: Page) => Number((await distanceLabel(page).first().innerText()).replace(/\D/g, ''));

test.describe('Раунд 13: автосохранение предпочтений (#2911c1)', () => {
  test('Автосохранение: PATCH при выборе и отпускании ползунков, возврат исходных @desktop @data', async ({ page }) => {
    // 1. Запомнить исходные `interested_in`, `pref_age_min/max`, `pref_distance_km` (REST токеном free).
    const apiReq = page.waitForRequest((r) => {
      const h = r.headers();
      return r.url().includes('/rest/v1/') && !!h['apikey'] && !!h['authorization'] && h['authorization'] !== `Bearer ${h['apikey']}`;
    });
    await page.goto(PREFS);
    await expect(page.getByText('העדפות חיפוש')).toBeVisible();
    await expect(page.getByText('מי מעניין אותי')).toBeVisible();
    const api = await apiFrom(page, await apiReq);
    const before = await readPrefs(api);
    const aMin = Number(before.pref_age_min), aMax = Number(before.pref_age_max), dist = Number(before.pref_distance_km);

    try {
      // Значения приходят из профиля после отрисовки — ждём, пока метки совпадут с профилем.
      await expect.poll(() => ageValues(page), { message: 'метки возраста = значения профиля' }).toEqual([aMin, Math.max(aMin, Math.min(aMax, 60))]);
      await expect(distanceLabel(page).first()).toHaveText(`${dist} ק״מ`);

      // 2. Нажать другую опцию «מי מעניין אותי» — ждать PATCH.
      const radios = page.getByRole('radio');
      await expect(radios).toHaveCount(4);
      // Выбранная опция отличается рамкой «border-white» (без прозрачности) — берём первую невыбранную.
      const idx = await radios.evaluateAll((els) => els.findIndex((e) => !/(^|\s)border-white(\s|$)/.test(e.className)));
      expect(idx, 'есть невыбранная опция «מי מעניין אותי»').toBeGreaterThanOrEqual(0);
      const interestPatch = page.waitForResponse((r) => isProfilePatch(r.request()) && 'interested_in' in patchBody(r.request()));
      await radios.nth(idx).click();
      const interestRes: Response = await interestPatch;
      // Шаг 2: PATCH `profiles` с новым `interested_in`; 2xx.
      expect(interestRes.ok(), 'PATCH interested_in → 2xx').toBeTruthy();
      const newInterest = patchBody(interestRes.request()).interested_in;
      expect(JSON.stringify(newInterest), 'interested_in изменился').not.toBe(JSON.stringify(before.interested_in));

      // 3. Перетащить левую ручку возраста мышью и отпустить.
      const newMin = aMin + 2 <= Math.min(aMax, 60) - 1 ? aMin + 2 : Math.max(18, aMin - 2);
      expect(newMin, 'новый минимум возраста отличается от исходного').not.toBe(aMin);
      const agePatch = page.waitForResponse((r) => isProfilePatch(r.request()) && patchBody(r.request()).pref_age_min === newMin);
      await dragHandleTo(page, 'min', newMin);
      // PATCH с новыми `pref_age_*` после отпускания; 2xx.
      expect((await agePatch).ok(), 'PATCH pref_age_min → 2xx').toBeTruthy();

      // Перетащить ручку расстояния; PATCH только после mouseup.
      const target = dist === 50 ? 25 : 50;
      const g = await distanceGeo(page);
      const xOf = (v: number) => g.x1 + ((v - 1) * (g.x100 - g.x1)) / 99;
      const distPatches: number[] = [];
      const onReq = (r: Request) => { if (isProfilePatch(r) && patchBody(r).pref_distance_km !== undefined) distPatches.push(Number(patchBody(r).pref_distance_km)); };
      await expect
        .poll(async () => {
          // Сразу после загрузки ползунок может не принять жест — повторяем захват, пока метка не сдвинется.
          await page.mouse.move(xOf(dist), g.y);
          await page.mouse.down();
          await page.mouse.move(xOf(dist) + Math.sign(xOf(target) - xOf(dist)) * 8, g.y, { steps: 4 });
          const moved = (await distanceValue(page)) !== dist;
          if (!moved) await page.mouse.up();
          return moved;
        }, { message: 'ручка расстояния захватывается', timeout: 10_000, intervals: [200, 300, 500] })
        .toBe(true);
      page.on('request', onReq);
      await page.mouse.move(xOf(target), g.y, { steps: 20 });
      const newDist = await distanceValue(page);
      expect(newDist, 'метка расстояния изменилась').not.toBe(dist);
      // До отпускания PATCH с новым расстоянием нет.
      expect(distPatches.filter((v) => v === newDist), 'PATCH до mouseup').toHaveLength(0);
      const distPatch = page.waitForResponse((r) => isProfilePatch(r.request()) && patchBody(r.request()).pref_distance_km === newDist);
      await page.mouse.up();
      expect((await distPatch).ok(), 'PATCH pref_distance_km → 2xx').toBeTruthy();
      page.off('request', onReq);

      // 4. Перезагрузить `/prefs?from=settings`; затем открыть `/settings`.
      await page.goto(PREFS);
      await expect(page.getByText('מי מעניין אותי')).toBeVisible();
      // Метки на экране совпадают с новыми значениями; кнопки «שמירה» нет.
      await expect.poll(() => ageValues(page)).toEqual([newMin, Math.max(newMin, Math.min(aMax, 60))]);
      await expect(distanceLabel(page).first()).toHaveText(`${newDist} ק״מ`);
      await expect(page.getByRole('button', { name: 'שמירה' })).toHaveCount(0);

      await page.goto('/settings');
      // Строка «העדפות חיפוש» в הגדרות: «עד N ק״מ • A–B».
      const maxText = aMax >= 60 ? '60\\+?' : String(aMax);
      await expect(page.getByText(new RegExp(`עד ${newDist} ק״מ.*${newMin}.${maxText}`)).first()).toBeVisible();
    } finally {
      // 5. `finally`: вернуть исходные значения (REST), перезагрузить, сверить.
      const back = await page.request.patch(`${api.base}/rest/v1/profiles?id=eq.${api.userId}`, {
        headers: { apikey: api.apikey, Authorization: api.auth, 'Content-Type': 'application/json', Prefer: 'return=minimal' },
        data: Object.fromEntries(KEYS.map((k) => [k, before[k]])),
        failOnStatusCode: false,
      });
      expect(back.ok(), `возврат предпочтений ${JSON.stringify(before)}`).toBeTruthy();
      await page.goto(PREFS);
      await expect(page.getByText('מי מעניין אותי')).toBeVisible();
      expect(await readPrefs(api), 'значения равны исходным').toEqual(before);
    }
  });
});
